test('invoiceTotals returns subtotal and total', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500 },
      { qty: 1, unitPrice: 120000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 205000);
  assert.equal(totals.total, 205000);
});

test('invoiceTotals works with single line', () => {
