test('invoiceTotals calculates discount on single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 8500);
  assert.equal(totals.total, 76500);
});

test('invoiceTotals handles multiple lines with different discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 10 },
      { qty: 5, unitPrice: 9500, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000 + 47500);
  assert.equal(totals.discount, 8500 + 9500);
  assert.equal(totals.total, 132500 - 18000);
});

